import{t as e}from"./api-7M9YWvHU.js";var t={async getGovernanceOverview(t=`7d`){return(await e.get(`/admin/governance`,{params:{period:t}})).data.data},async searchAuditLogs(t){return(await e.get(`/admin/governance/audit`,{params:t})).data},async getAuditLogShow(t){return(await e.get(`/admin/governance/audit/${t}`)).data.data},async getIncidentTimeline(t){return(await e.get(`/admin/governance/incidents/${t}/timeline`)).data.data},async getIntegrityStatus(t){return(await e.get(`/admin/governance/integrity`,{params:{domain:t}})).data.data},async getContinuityReadiness(){return(await e.get(`/admin/governance/continuity`)).data.data},getReportExportUrl(e=`30d`,t=`csv`){return`/admin/governance/report?period=${e}&format=${t}`}};export{t};